use super::conversion::Segment;
use std::{collections::HashMap, sync::LazyLock};

// Group by the first letter while preserving each group's longest-first order.
const KANA: &str = include_str!("romaji.txt");
// Generated by tools/build_dictionary.py from the Mozc open source dictionary.
const WORDS: &str = include_str!("dictionary.tsv");
const MAX_CANDIDATES: usize = 14;
// Words that follow a noun inside one clause (文節).
const PARTICLES: &[&str] = &[
    "から",
    "まで",
    "より",
    "だけ",
    "ほど",
    "など",
    "って",
    "でも",
    "には",
    "とは",
    "では",
    "のは",
    "ので",
    "のに",
    "けど",
    "ですが",
    "でした",
    "です",
    "だった",
    "だ",
    "は",
    "が",
    "を",
    "に",
    "へ",
    "で",
    "と",
    "も",
    "の",
    "や",
    "か",
    "ね",
    "よ",
    "な",
    "わ",
    "ぞ",
    "さ",
    "し",
    "ば",
    "ぜ",
];
type RomanSyllable = (&'static str, &'static str);
static INDEX: LazyLock<HashMap<&'static str, &'static str>> = LazyLock::new(|| {
    WORDS
        .lines()
        .filter_map(|line| line.split_once('\t'))
        .collect()
});
static SYLLABLES: LazyLock<[Vec<RomanSyllable>; 26]> = LazyLock::new(|| {
    let mut groups: [Vec<RomanSyllable>; 26] = Default::default();
    for (roman, kana) in KANA
        .split_ascii_whitespace()
        .filter_map(|entry| entry.split_once('='))
    {
        groups[(roman.as_bytes()[0] - b'a') as usize].push((roman, kana));
    }
    groups
});

pub fn kana(input: &str, finalizing: bool) -> String {
    let mut result = String::new();
    let lowercase = input.to_ascii_lowercase();
    let mut rest = lowercase.as_str();
    while let Some(&first) = rest.as_bytes().first() {
        let next = rest.as_bytes().get(1).copied();
        // A bare run of three or more n's is literal. Keep the explicit nn and n'
        // rules and normal syllables such as the nn in こんにちは.
        if rest.starts_with("nnn") {
            let len = rest.bytes().take_while(|&byte| byte == b'n').count();
            if rest
                .as_bytes()
                .get(len)
                .is_none_or(|byte| !byte.is_ascii_alphabetic() && *byte != b'\'')
            {
                let offset = input.len() - rest.len();
                result.push_str(&input[offset..offset + len]);
                rest = &rest[len..];
                continue;
            }
        }
        if first == b'n' {
            match next {
                Some(b'n')
                    if rest
                        .as_bytes()
                        .get(2)
                        .is_some_and(|next| b"aiueoy".contains(next)) =>
                {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                Some(b'n' | b'\'') => {
                    result.push('ん');
                    rest = &rest[2..];
                    continue;
                }
                Some(next) if next.is_ascii_alphabetic() && !b"aiueoy".contains(&next) => {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                None if finalizing => {
                    result.push('ん');
                    break;
                }
                Some(next) if !next.is_ascii_alphabetic() => {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                _ => {}
            }
        }
        if next == Some(first)
            && first.is_ascii_lowercase()
            && !b"aiueon".contains(&first)
            && syllable(&rest[1..]).is_some()
        {
            result.push('っ');
            rest = &rest[1..];
            continue;
        }
        if let Some((roman, kana)) = syllable(rest) {
            result.push_str(kana);
            rest = &rest[roman.len()..];
        } else {
            let ch = input[input.len() - rest.len()..].chars().next().unwrap();
            result.push(key_label(ch));
            rest = &rest[ch.len_utf8()..];
        }
    }
    result
}

pub fn key_label(key: char) -> char {
    match key {
        ',' => '、',
        '.' => '。',
        '-' => 'ー',
        '¥' => '￥',
        key if key.is_ascii_punctuation() => char::from_u32(key as u32 + 0xfee0).unwrap(),
        _ => key,
    }
}

fn syllable(rest: &str) -> Option<RomanSyllable> {
    let first = *rest.as_bytes().first()?;
    if !first.is_ascii_lowercase() {
        return None;
    }
    SYLLABLES[(first - b'a') as usize]
        .iter()
        .copied()
        .find(|(roman, _)| rest.starts_with(roman))
}

pub fn katakana(value: &str) -> String {
    value
        .chars()
        .map(|c| match c {
            'ぁ'..='ゖ' => char::from_u32(c as u32 + 0x60).unwrap(),
            _ => c,
        })
        .collect()
}

pub fn halfwidth(value: &str) -> String {
    const KANA: &str = "ヲァィゥェォャュョッーアイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワン";
    const VOICED: &str = "ガギグゲゴザジズゼゾダヂヅデドバビブベボヴヷヺ";
    const BASE: &str = "カキクケコサシスセソタチツテトハヒフヘホウワヲ";
    const SEMIVOICED: &str = "パピプペポ";

    let mut result = String::new();
    for ch in value.chars() {
        let (base, mark) = if let Some(index) = VOICED.chars().position(|voiced| voiced == ch) {
            (BASE.chars().nth(index).unwrap(), Some('ﾞ'))
        } else if let Some(index) = SEMIVOICED.chars().position(|voiced| voiced == ch) {
            ("ハヒフヘホ".chars().nth(index).unwrap(), Some('ﾟ'))
        } else {
            (ch, None)
        };
        let narrow = match base {
            '、' => ',',
            '。' => '.',
            '「' => '｢',
            '」' => '｣',
            '・' => '･',
            '\u{3099}' | '゛' => 'ﾞ',
            '\u{309a}' | '゜' => 'ﾟ',
            '￥' => '¥',
            '！'..='～' => char::from_u32(base as u32 - 0xfee0).unwrap(),
            _ => KANA
                .chars()
                .position(|kana| kana == base)
                .and_then(|index| char::from_u32(0xff66 + index as u32))
                .unwrap_or(base),
        };
        result.push(narrow);
        result.extend(mark);
    }
    result
}

/// Loads the dictionary index now so that the first conversion does not stall.
pub fn warm_up() {
    LazyLock::force(&INDEX);
}

/// Words with exactly this reading as `(is_inflected_form, surface)`.
fn entries(reading: &str) -> impl Iterator<Item = (bool, &'static str)> {
    INDEX
        .get(reading)
        .into_iter()
        .flat_map(|tokens| tokens.split(' '))
        .filter_map(|token| {
            let surface = token.get(1..)?;
            Some((token.starts_with('v'), surface))
        })
}

/// Whole-reading candidates for the prediction bar while the user is typing.
pub fn dictionary(reading: &str) -> impl Iterator<Item = &'static str> {
    let mut seen = Vec::new();
    entries(reading)
        .map(|(_, surface)| surface)
        .filter(move |surface| {
            let fresh = !seen.contains(surface);
            seen.push(*surface);
            fresh
        })
}

fn is_particles(tail: &str) -> bool {
    tail.is_empty()
        || PARTICLES
            .iter()
            .any(|particle| tail.strip_prefix(particle).is_some_and(is_particles))
}

/// Candidates for one clause. `best` is the clause as the sentence-level
/// conversion of the system IME wrote it.
fn clause_candidates(reading: &str, best: Option<&str>) -> Vec<String> {
    fn push(candidates: &mut Vec<String>, value: &str) {
        if !value.is_empty() && !candidates.iter().any(|known| known == value) {
            candidates.push(value.to_owned());
        }
    }

    let mut candidates = Vec::new();
    if let Some(best) = best {
        push(&mut candidates, best);
    }
    for (_, surface) in entries(reading) {
        push(&mut candidates, surface);
    }
    let splits: Vec<usize> = reading
        .char_indices()
        .map(|(index, _)| index)
        .skip(1)
        .collect();
    // A head word with a tail: a noun with particles, or an inflected stem with endings.
    for &split in splits.iter().rev() {
        if candidates.len() >= MAX_CANDIDATES {
            break;
        }
        let (head, tail) = reading.split_at(split);
        let nominal = is_particles(tail);
        // A one-letter head of a long clause is almost always noise.
        if split == head.chars().next().map_or(0, char::len_utf8) && !nominal && splits.len() > 2 {
            continue;
        }
        for (_, surface) in entries(head)
            .filter(|(inflected, _)| *inflected != nominal)
            .take(3)
        {
            push(&mut candidates, &format!("{surface}{tail}"));
        }
    }
    candidates.truncate(MAX_CANDIDATES);
    push(&mut candidates, reading);
    let katakana = katakana(reading);
    push(&mut candidates, &katakana);
    let halfwidth = halfwidth(&katakana);
    if !candidates.contains(&halfwidth) {
        candidates.insert(candidates.len().min(2), halfwidth);
    }
    if reading.chars().all(|ch| ch == 'ー') {
        push(&mut candidates, &"-".repeat(reading.chars().count()));
    }
    candidates
}

/// Splits a reading into clauses without the system IME: a dictionary word with
/// the particles that follow it.
fn split_clauses(reading: &str) -> Vec<&str> {
    let mut clauses = Vec::new();
    let mut rest = reading;
    while !rest.is_empty() {
        let is_kana = |ch| matches!(ch, 'ぁ'..='ゖ' | 'ー');
        let kana_run = is_kana(rest.chars().next().unwrap());
        let run_end = rest
            .char_indices()
            .find_map(|(index, ch)| (is_kana(ch) != kana_run).then_some(index))
            .unwrap_or(rest.len());
        if !kana_run {
            clauses.push(&rest[..run_end]);
            rest = &rest[run_end..];
            continue;
        }
        let mut ends: Vec<usize> = rest[..run_end]
            .char_indices()
            .skip(1)
            .filter_map(|(index, ch)| {
                (!"ぁぃぅぇぉゃゅょっゎゕゖー".contains(ch) && !rest[..index].ends_with('っ'))
                    .then_some(index)
            })
            .collect();
        ends.push(run_end);
        let head = ends
            .into_iter()
            .rev()
            .find(|&end| entries(&rest[..end]).next().is_some());
        let mut end = head.unwrap_or(run_end);
        while let Some(particle) = PARTICLES
            .iter()
            .find(|particle| rest[end..].starts_with(*particle))
        {
            end += particle.len();
        }
        clauses.push(&rest[..end]);
        rest = &rest[end..];
    }
    clauses
}

/// Builds the clauses of a conversion. `hints` are `(reading, text)` clauses
/// from the system IME. They are used only when they add up to `reading`.
pub fn segments(reading: &str, hints: &[(String, String)]) -> Vec<Segment> {
    let joined: String = hints.iter().map(|(reading, _)| reading.as_str()).collect();
    let clauses: Vec<(&str, Option<&str>)> = if !hints.is_empty() && joined == reading {
        hints
            .iter()
            .map(|(reading, text)| (reading.as_str(), Some(text.as_str())))
            .collect()
    } else {
        split_clauses(reading)
            .into_iter()
            .map(|clause| (clause, None))
            .collect()
    };
    clauses
        .into_iter()
        .map(|(reading, best)| Segment {
            reading: reading.to_owned(),
            candidates: clause_candidates(reading, best),
            selected: 0,
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::kana;

    #[test]
    fn repeated_consonants_without_a_syllable_remain_literal() {
        for consonant in "bcdfghjklmnpqrstvwxyz".chars() {
            let input = consonant.to_string().repeat(3);
            assert_eq!(kana(&input, false), input);
            assert_eq!(kana(&input, true), input);
        }
        assert_eq!(kana("kitte", true), "きって");
        assert_eq!(kana("aaa", true), "あああ");
        assert_eq!(kana("nn", true), "ん");
    }
}
